SELECT (SELECT relrowsecurity FROM pg_class WHERE oid='storage.objects'::regclass) AND
(SELECT count(*)=3 AND bool_and(c.relrowsecurity AND NOT has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('service_role',c.oid,'SELECT,INSERT,UPDATE,DELETE')) FROM pg_class c WHERE c.oid IN(to_regclass('petro_private.merchant_payout_proof_intents'),to_regclass('petro_private.merchant_payout_proof_acceptances'),to_regclass('petro_private.merchant_payout_proof_commands')))
AND(SELECT count(*)=5 AND bool_and(p.prosecdef AND p.proconfig=ARRAY['search_path=""']::text[] AND has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('service_role',p.oid,'EXECUTE')) FROM pg_proc p WHERE p.oid IN(to_regprocedure('public.petro_merchant_payout_proof_file(uuid,text)'),to_regprocedure('public.petro_merchant_payout_proofs(uuid)'),to_regprocedure('public.petro_create_merchant_payout_proof(uuid,bigint,text,text,bigint,text)'),to_regprocedure('public.petro_accept_merchant_payout_proof(uuid,text,text)'),to_regprocedure('petro_private.can_access_merchant_payout_proof(text,text)')))
AND(SELECT count(*)=2 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname IN('petro_merchant_payout_proof_read','petro_merchant_payout_proof_upload')) AS present;
